import{_ as t,o as a,c as r,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Service-entry Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/40-job-contract-evidence-audit.md","filePath":"reference/40-job-contract-evidence-audit.md","lastUpdated":1788532705000}'),o={name:"reference/40-job-contract-evidence-audit.md"};function d(i,e,c,s,h,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="service-entry-source-profile" tabindex="-1">Service-entry Source Profile <a class="header-anchor" href="#service-entry-source-profile" aria-label="Permalink to &quot;Service-entry Source Profile&quot;">​</a></h1><h2 id="scope-and-authority" tabindex="-1">Scope and authority <a class="header-anchor" href="#scope-and-authority" aria-label="Permalink to &quot;Scope and authority&quot;">​</a></h2><p>The <code>job</code> compatibility key now means the employee-side act of <strong>entering employment / starting service</strong>. It does not cover offer acceptance, signing a modern employment or commercial contract, incorporation, or hiring staff.</p><p>The verified claim <code>muhurta.service_entry</code> uses Rama Daivajna, <em>Muhurta Chintamani</em>, undated Sanskrit text with Hindi commentary, Nakshatra-prakarana, “Entering the service of a master,” verse 26, printed page 38 (Internet Archive OCR lines 2565–2577).</p><h2 id="exact-crosswalk" tabindex="-1">Exact crosswalk <a class="header-anchor" href="#exact-crosswalk" aria-label="Permalink to &quot;Exact crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source criterion</th><th>Implementation</th><th>Boundary</th></tr></thead><tbody><tr><td>Ashwini, Pushya, Hasta, Chitra, Anuradha, Mrigashira and Revati</td><td>Exact <code>allowed_nakshatras</code></td><td>Hard day gate</td></tr><tr><td>Wednesday, Friday, Sunday and Thursday</td><td>Exact <code>allowed_varas</code></td><td>Hard day gate</td></tr><tr><td>Benefic in Lagna</td><td>Manual check</td><td>Mandatory chart review</td></tr><tr><td>Surya or Mangala in the 10th or 11th</td><td><code>ELECTION_CHART_RULES[job]</code></td><td>Drik browser tie-break preference only when it passes across every sampled state (edges and both sides of known interior Lagna transitions); absence does not reject</td></tr><tr><td>Employer/employee Yoni friendship</td><td>Manual check</td><td>Requires both birth Nakshatras</td></tr><tr><td>Friendship between both Janma-Rasi lords</td><td>Manual check</td><td>Requires both natal Rasis</td></tr></tbody></table><p><code>manual_prerequisites = true</code> caps results below Excellent until the chart and two-person compatibility checks are complete. The former Amrit Choghadiya, Nanda Tithi and Sthira-Lagna proxies have been removed.</p><p>Python/MCP retain all chart wording as <code>manual_checks</code>; only the Drik browser performs the bounded candidate-time chart post-screen. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p><p>The separately inspected Sandhana verse concerns peace, alliance or friendship and is not treated as authority for a modern contract. Employment terms, labour law, compensation, benefits and workplace safety take precedence.</p>',9)])])}const m=t(o,[["render",d]]);export{u as __pageData,m as default};
